ADMIN_HTML = r'''<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>chat2api Console</title>
<style>
:root{color-scheme:dark;--bg:#09101d;--panel:#111a2b;--panel2:#0d1525;--muted:#8795ad;--line:#25324b;--ok:#39d6a1;--bad:#ff727d;--warn:#ffd166;--text:#eef4ff;--accent:#72a7ff;--accent2:#365d9b}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.55 system-ui,-apple-system,"Segoe UI",sans-serif}button,input,select,textarea{font:inherit}.shell{display:grid;grid-template-columns:220px 1fr;min-height:100vh}.side{border-right:1px solid var(--line);background:#0b1322;padding:22px 14px;position:sticky;top:0;height:100vh}.brand{font-size:22px;font-weight:850;padding:0 10px 20px}.brand small{display:block;font-size:11px;font-weight:500;color:var(--muted);margin-top:2px}.nav button{width:100%;text-align:left;border:0;background:transparent;color:var(--muted);padding:10px 12px;border-radius:9px;margin:2px 0;cursor:pointer}.nav button:hover,.nav button.active{background:#17233a;color:var(--text)}.main{min-width:0}.top{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:16px 24px;border-bottom:1px solid var(--line);background:rgba(9,16,29,.9);position:sticky;top:0;z-index:8;backdrop-filter:blur(10px)}.title{font-size:18px;font-weight:750}.auth{display:flex;gap:8px;min-width:min(100%,560px)}input,select,textarea,button.action{border:1px solid var(--line);border-radius:9px;background:#0c1526;color:var(--text);padding:9px 11px}.auth input{flex:1}.action{cursor:pointer;background:#19345f!important}.action.secondary{background:#121e32!important}.action.danger{background:#4a2029!important;color:#ffc0c5}.action.good{background:#144634!important}.content{padding:24px;max-width:1600px;margin:auto}.message{margin-bottom:14px;color:var(--muted)}.view{display:none}.view.active{display:block}.grid{display:grid;grid-template-columns:repeat(6,minmax(120px,1fr));gap:12px;margin-bottom:16px}.card,.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:16px}.card .n{font-size:25px;font-weight:850;margin-top:4px}.muted{color:var(--muted)}.ok{color:var(--ok)}.bad{color:var(--bad)}.warn{color:var(--warn)}.panels{display:grid;grid-template-columns:1fr 1fr;gap:14px}.wide{grid-column:1/-1}.panel h2{font-size:16px;margin:0 0 12px}.toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:0 0 12px}.toolbar input,.toolbar select{min-width:130px}.scroll{overflow:auto;max-height:600px}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{text-align:left;padding:9px 10px;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--muted);font-weight:650;position:sticky;top:0;background:var(--panel);z-index:1}tr.clickable{cursor:pointer}tr.clickable:hover{background:#172137}code,pre{font-family:ui-monospace,SFMono-Regular,Consolas,monospace}code{color:#c8d9ff}.pill{display:inline-block;padding:2px 7px;border-radius:999px;background:#1a2943}.pill.ok{background:#123a30}.pill.bad{background:#45232b}.pill.warn{background:#493b17}.split{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(320px,.65fr);gap:14px}.formgrid{display:grid;grid-template-columns:1fr 160px auto;gap:8px}.secret{background:#07101e;border:1px solid var(--ok);border-radius:12px;padding:14px;margin:12px 0;word-break:break-all}.secret code{font-size:14px;color:#b8ffdf}.doc h2{margin-top:28px}.doc h3{margin-top:22px}.doc p,.doc li{color:#c9d3e4}.codebox{position:relative;background:#07101e;border:1px solid var(--line);border-radius:12px;padding:14px;overflow:auto;white-space:pre-wrap}.copy{position:absolute;right:8px;top:8px}.playgrid{display:grid;grid-template-columns:minmax(320px,.7fr) minmax(0,1.3fr);gap:14px}.field{margin-bottom:12px}.field label{display:block;color:var(--muted);margin-bottom:5px}.field input,.field select,.field textarea{width:100%}.field textarea{min-height:220px;resize:vertical}.output{min-height:260px;max-height:520px;overflow:auto;background:#07101e;border:1px solid var(--line);border-radius:12px;padding:14px;white-space:pre-wrap;word-break:break-word}.raw{max-height:260px;overflow:auto;font-size:12px}.detail pre{white-space:pre-wrap;word-break:break-word;font-size:12px}.rowactions{display:flex;gap:6px}.rowactions button{padding:5px 8px}.pager{display:flex;gap:10px;align-items:center;justify-content:flex-end;margin-top:12px}.footer{color:var(--muted);margin-top:18px}.hidden{display:none!important}
@media(max-width:1100px){.shell{grid-template-columns:1fr}.side{height:auto;position:static;border-right:0;border-bottom:1px solid var(--line)}.brand{padding-bottom:10px}.nav{display:flex;overflow:auto}.nav button{width:auto;white-space:nowrap}.grid{grid-template-columns:repeat(2,1fr)}.panels,.split,.playgrid{grid-template-columns:1fr}.wide{grid-column:auto}.top{position:static}.formgrid{grid-template-columns:1fr}}
</style>
</head>
<body><div class="shell">
<aside class="side"><div class="brand">chat2api<small>Server Console · v0.4</small></div><div class="nav">
<button data-view="overview">概览</button><button data-view="keys">API Key</button><button data-view="requests">请求记录</button><button data-view="docs">开发文档</button><button data-view="playground">测试场</button>
</div></aside>
<main class="main"><header class="top"><div><div id="pageTitle" class="title">概览</div><div id="statusText" class="muted">输入管理员主密钥后连接</div></div><div class="auth"><input id="adminKey" type="password" autocomplete="off" placeholder="CHAT2API_API_KEY（管理员主密钥）"/><button class="action" id="connectBtn">连接</button><button class="action secondary" id="refreshBtn">刷新</button></div></header>
<div class="content">
<section id="view-overview" class="view">
<div class="grid"><div class="card"><div class="muted">在线扩展</div><div id="statExtensions" class="n">-</div></div><div class="card"><div class="muted">桌面客户端</div><div id="statAgents" class="n">-</div></div><div class="card"><div class="muted">请求记录</div><div id="statRequests" class="n">-</div></div><div class="card"><div class="muted">成功率</div><div id="statSuccess" class="n">-</div></div><div class="card"><div class="muted">平均首 Token</div><div id="statFirst" class="n">-</div></div><div class="card"><div class="muted">估算 Token</div><div id="statTokens" class="n">-</div></div></div>
<div class="panels"><div class="panel"><h2>Chrome 扩展</h2><div class="scroll"><table><thead><tr><th>ID</th><th>名称</th><th>状态</th><th>当前模型</th><th>版本</th></tr></thead><tbody id="clientsBody"></tbody></table></div></div><div class="panel"><h2>模型目录</h2><div class="scroll"><table><thead><tr><th>Model ID</th><th>标签</th><th>客户端</th></tr></thead><tbody id="modelsBody"></tbody></table></div></div><div class="panel wide"><h2>最近请求</h2><div class="scroll"><table><thead><tr><th>时间</th><th>状态</th><th>API Key</th><th>请求模型</th><th>实际模型</th><th>首 Token</th><th>总耗时</th><th>Token</th></tr></thead><tbody id="recentBody"></tbody></table></div></div></div>
</section>
<section id="view-keys" class="view"><div class="panel"><h2>创建业务 API Key</h2><div class="formgrid"><input id="newKeyName" placeholder="名称，例如：手机 App / 测试脚本"/><input id="newKeyDays" type="number" min="1" max="3650" placeholder="有效天数，可留空"/><button class="action good" id="createKeyBtn">创建 Key</button></div><div id="createdSecret" class="secret hidden"><div class="warn">完整 Key 只显示这一次，请立即保存。</div><div style="display:flex;gap:8px;margin-top:8px"><code id="createdToken" style="flex:1"></code><button class="action secondary" id="copyTokenBtn">复制</button></div></div></div><div class="panel" style="margin-top:14px"><h2>令牌列表</h2><div class="scroll"><table><thead><tr><th>名称</th><th>前缀</th><th>状态</th><th>权限</th><th>创建</th><th>过期</th><th>最后使用</th><th>请求/Token</th><th>操作</th></tr></thead><tbody id="keysBody"></tbody></table></div></div><div class="footer">管理员主密钥来自服务器 <code>.env</code>，不能在网页删除。业务 Key 只允许调用 <code>/v1/*</code>，不能访问管理接口和扩展配对码。</div></section>
<section id="view-requests" class="view"><div class="split"><div class="panel"><h2>请求记录</h2><div class="toolbar"><input id="rqSearch" placeholder="request ID / 错误 / 客户端"/><select id="rqStatus"><option value="">全部状态</option><option value="completed">completed</option><option value="error">error</option></select><input id="rqModel" placeholder="模型"/><select id="rqKey"><option value="">全部 Key</option></select><button class="action" id="rqFilter">筛选</button></div><div class="scroll"><table><thead><tr><th>时间</th><th>状态</th><th>Key</th><th>模型</th><th>实际</th><th>首 Token</th><th>总耗时</th><th>Token</th></tr></thead><tbody id="requestsBody"></tbody></table></div><div class="pager"><button class="action secondary" id="prevPage">上一页</button><span id="pageInfo" class="muted">-</span><button class="action secondary" id="nextPage">下一页</button></div></div><div class="panel detail"><h2>请求详情</h2><div id="requestDetail" class="muted">点击左侧记录查看完整诊断。</div></div></div></section>
<section id="view-docs" class="view doc"><div class="panel"><h1>chat2api 开发文档</h1><p>chat2api 将已登录 ChatGPT 的 Chrome 页面桥接为 OpenAI 风格 HTTP API。业务客户端使用管理面板创建的 API Key；服务器管理员主密钥也兼容，但不建议分发。</p><h2>连接信息</h2><table><tbody><tr><th>Base URL</th><td><code id="docBase"></code></td></tr><tr><th>Chat Completions</th><td><code>/v1/chat/completions</code></td></tr><tr><th>Models</th><td><code>/v1/models</code></td></tr><tr><th>鉴权</th><td><code>Authorization: Bearer YOUR_API_KEY</code></td></tr><tr><th>默认模型</th><td><code>default</code>（完全不操作 ChatGPT 模型 UI）</td></tr></tbody></table><h2>快速开始：curl</h2><div class="codebox"><button class="action secondary copy" data-copy="curlCode">复制</button><pre id="curlCode"></pre></div><h2>Python（OpenAI SDK）</h2><div class="codebox"><button class="action secondary copy" data-copy="pythonCode">复制</button><pre id="pythonCode"></pre></div><h2>流式 SSE</h2><p>设置 <code>stream:true</code> 后返回 <code>text/event-stream</code>。正文位于 <code>choices[0].delta.content</code>。最后一个 stop chunk 会附带估算 <code>usage</code>、实际模型与耗时诊断，随后发送 <code>data: [DONE]</code>。</p><div class="codebox"><pre>data: {"choices":[{"delta":{"content":"..."}}]}

data: {"choices":[{"delta":{},"finish_reason":"stop"}],"usage":{...},"chat2api":{...}}

data: [DONE]</pre></div><h2>模型</h2><p><code>GET /v1/models</code> 返回当前在线扩展已发现的模型。<code>default</code> 和 <code>chatgpt-web</code> 为零操作路径；指定例如 <code>gpt-5.6-sol-high</code> 时扩展会现场检测并按需切换。</p><h2>额外参数</h2><table><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>client_id</code></td><td>多个 Chrome 扩展在线时指定目标扩展。</td></tr><tr><td><code>prompt_mode</code></td><td><code>last_user</code>（默认）或 <code>full</code>。</td></tr><tr><td><code>timeout</code></td><td>请求超时秒数，5–900。</td></tr><tr><td><code>stream</code></td><td>是否使用 SSE 流式输出。</td></tr></tbody></table><h2>常见状态码</h2><table><tbody><tr><th>401</th><td>业务 API Key 无效、停用、撤销或过期。</td></tr><tr><th>403</th><td>使用业务 Key 访问了管理员接口。</td></tr><tr><th>409</th><td>目标扩展忙或多个扩展在线但未指定 client_id。</td></tr><tr><th>503</th><td>Chrome 扩展离线，且桌面唤醒没有及时恢复。</td></tr><tr><th>504</th><td>等待 ChatGPT 回复超时。</td></tr></tbody></table><p><a href="/docs" target="_blank" style="color:var(--accent)">打开 FastAPI Swagger /docs →</a></p></div></section>
<section id="view-playground" class="view"><div class="playgrid"><div class="panel"><h2>请求</h2><div class="field"><label>测试 API Key</label><input id="pgKey" type="password" placeholder="留空则使用上方管理员主密钥"/></div><div class="field"><label>模型</label><select id="pgModel"><option value="default">default</option></select></div><div class="field"><label>Prompt 模式</label><select id="pgMode"><option value="last_user">last_user</option><option value="full">full</option></select></div><div class="field"><label><input id="pgStream" type="checkbox" checked style="width:auto"/> 流式请求</label></div><div class="field"><label>Prompt</label><textarea id="pgPrompt" placeholder="输入要发送给 ChatGPT 的内容">请只回复：chat2api 测试场调用成功</textarea></div><button class="action good" id="pgRun">运行测试</button></div><div class="panel"><h2>输出</h2><div id="pgState" class="muted" style="margin-bottom:8px">等待测试。</div><div id="pgOutput" class="output"></div><h2 style="margin-top:16px">Usage / Diagnostics</h2><div id="pgMeta" class="codebox"><pre>-</pre></div><details style="margin-top:14px"><summary>原始响应 / SSE</summary><pre id="pgRaw" class="codebox raw"></pre></details></div></div></section>
<div class="footer">Token 为 <code>chat2api-heuristic-v1</code> 估算值，不是 ChatGPT 官方 usage。请求历史默认不保存完整 Prompt 与回复正文。</div>
</div></main></div>
<script>
const INITIAL_VIEW='__INITIAL_VIEW__'; const $=id=>document.getElementById(id); const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); const fmtMs=v=>v==null?'-':(Number(v)<1000?Math.round(v)+' ms':(Number(v)/1000).toFixed(1)+' s'); const fmtTime=v=>v?String(v).replace('T',' ').slice(0,19):'-'; const titles={overview:'概览',keys:'API Key',requests:'请求记录',docs:'开发文档',playground:'测试场'}; let overview=null; let requestOffset=0; const requestLimit=50;
function adminKey(){return sessionStorage.getItem('chat2api_admin_key')||''} $('adminKey').value=adminKey();
function setStatus(text,cls='muted'){$('statusText').className=cls;$('statusText').textContent=text}
function authHeaders(key=adminKey()){return {'Authorization':'Bearer '+key}}
async function api(path,{method='GET',body=null,key=null}={}){const headers=authHeaders(key??adminKey());if(body!==null)headers['Content-Type']='application/json';const r=await fetch(path,{method,headers,body:body===null?null:JSON.stringify(body),cache:'no-store'});const text=await r.text();let data;try{data=text?JSON.parse(text):{}}catch(_){data={detail:text}}if(!r.ok)throw new Error((data.detail||data.error||r.status+' '+text));return data}
function showView(name){document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));document.querySelectorAll('.nav button').forEach(v=>v.classList.toggle('active',v.dataset.view===name));$('view-'+name)?.classList.add('active');$('pageTitle').textContent=titles[name]||name;location.hash=name;if(name==='overview')loadOverview();if(name==='keys')loadKeys();if(name==='requests')loadRequests();if(name==='docs')renderDocs();if(name==='playground')loadPlaygroundModels()}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('connectBtn').onclick=()=>{sessionStorage.setItem('chat2api_admin_key',$('adminKey').value.trim());loadOverview()};$('refreshBtn').onclick=()=>showView((location.hash||'#'+INITIAL_VIEW).slice(1));
function pill(text,type=''){return `<span class="pill ${type}">${esc(text)}</span>`}
function actualModel(r){const d=r.diagnostics||{};return d.actual_model||[d.actual_family,d.actual_reasoning].filter(Boolean).join('-')||'-'}
async function loadOverview(){if(!adminKey()){setStatus('请输入管理员主密钥 CHAT2API_API_KEY');return}try{overview=await api('/api/admin/overview');setStatus('已连接 · v'+overview.version+' · '+new Date().toLocaleTimeString(),'ok');const s=overview.telemetry||{};$('statExtensions').textContent=overview.health?.online_extensions??0;$('statAgents').textContent=overview.health?.online_desktop_agents??0;$('statRequests').textContent=s.retained_requests??0;$('statSuccess').textContent=(s.success_rate??100)+'%';$('statFirst').textContent=fmtMs(s.avg_first_token_ms);$('statTokens').textContent=s.estimated_total_tokens??0;$('clientsBody').innerHTML=(overview.clients||[]).map(c=>`<tr><td><code>${esc(c.client_id)}</code></td><td>${esc(c.name)}</td><td>${pill(c.online?(c.busy?'busy':'online'):'offline',c.online?(c.busy?'warn':'ok'):'bad')}</td><td>${esc(c.metadata?.current_model||'-')}</td><td>${esc(c.version||'-')}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">暂无客户端</td></tr>';$('modelsBody').innerHTML=(overview.models||[]).map(m=>`<tr><td><code>${esc(m.id)}</code></td><td>${esc(m.label||'')}</td><td>${esc((m.clients||[]).join(', ')||'-')}</td></tr>`).join('')||'<tr><td colspan="3" class="muted">暂无模型</td></tr>';$('recentBody').innerHTML=(overview.recent_requests||[]).map(r=>`<tr><td>${fmtTime(r.recorded_at)}</td><td>${pill(r.status||'-',r.status==='completed'?'ok':'bad')}</td><td>${esc(r.api_key_name||r.api_key_id||'-')}</td><td><code>${esc(r.requested_model||'-')}</code></td><td><code>${esc(actualModel(r))}</code></td><td>${fmtMs(r.timings?.first_token_ms)}</td><td>${fmtMs(r.timings?.total_ms)}</td><td>${esc(r.usage?.total_tokens??0)}</td></tr>`).join('')||'<tr><td colspan="8" class="muted">暂无请求</td></tr>';fillModelOptions();fillKeyFilter(overview.api_keys||[])}catch(e){setStatus('连接失败：'+e.message,'bad')}}
function fillModelOptions(){const select=$('pgModel'),current=select.value||'default',models=overview?.models||[];const ids=['default',...models.map(m=>m.id).filter(id=>id!=='default')];select.innerHTML=[...new Set(ids)].map(id=>`<option value="${esc(id)}">${esc(id)}</option>`).join('');if([...select.options].some(o=>o.value===current))select.value=current}
function fillKeyFilter(keys){const current=$('rqKey').value;$('rqKey').innerHTML='<option value="">全部 Key</option>'+keys.map(k=>`<option value="${esc(k.key_id)}">${esc(k.name)} (${esc(k.key_id)})</option>`).join('');$('rqKey').value=current}
async function loadKeys(){if(!adminKey())return setStatus('请先连接管理员主密钥','bad');try{const data=await api('/api/admin/keys');fillKeyFilter(data.data||[]);$('keysBody').innerHTML=(data.data||[]).map(k=>{const state=k.revoked_at?pill('revoked','bad'):k.expired?pill('expired','bad'):k.enabled?pill('enabled','ok'):pill('disabled','warn');const stats=`${k.request_count??0} / ${k.estimated_tokens??0}`;let actions='';if(k.managed&&!k.revoked_at){actions=`<div class="rowactions"><button class="action secondary" onclick="toggleKey('${esc(k.key_id)}',${!k.enabled})">${k.enabled?'停用':'启用'}</button><button class="action danger" onclick="revokeKey('${esc(k.key_id)}')">撤销</button></div>`}else if(!k.managed){actions='<span class="muted">.env 管理</span>'}return `<tr><td>${esc(k.name)}</td><td><code>${esc(k.prefix||'-')}</code></td><td>${state}</td><td>${esc((k.scopes||[]).join(', '))}</td><td>${fmtTime(k.created_at)}</td><td>${fmtTime(k.expires_at)}</td><td>${fmtTime(k.last_used_at)}</td><td>${stats}</td><td>${actions}</td></tr>`}).join('')||'<tr><td colspan="9">暂无 Key</td></tr>';setStatus('令牌列表已刷新','ok')}catch(e){setStatus('加载 Key 失败：'+e.message,'bad')}}
$('createKeyBtn').onclick=async()=>{const name=$('newKeyName').value.trim();if(!name)return setStatus('请输入 Key 名称','bad');const days=Number($('newKeyDays').value||0);try{const data=await api('/api/admin/keys',{method:'POST',body:{name,expires_in_days:days||null}});$('createdToken').textContent=data.token;$('createdSecret').classList.remove('hidden');$('newKeyName').value='';$('newKeyDays').value='';await loadKeys()}catch(e){setStatus('创建失败：'+e.message,'bad')}};$('copyTokenBtn').onclick=()=>navigator.clipboard.writeText($('createdToken').textContent||'');
async function toggleKey(id,enabled){try{await api('/api/admin/keys/'+encodeURIComponent(id),{method:'PATCH',body:{enabled}});await loadKeys()}catch(e){setStatus('修改失败：'+e.message,'bad')}} async function revokeKey(id){if(!confirm('撤销后该 API Key 将永久失效，确定继续？'))return;try{await api('/api/admin/keys/'+encodeURIComponent(id),{method:'DELETE'});await loadKeys()}catch(e){setStatus('撤销失败：'+e.message,'bad')}} window.toggleKey=toggleKey;window.revokeKey=revokeKey;
function requestQuery(){const p=new URLSearchParams({limit:String(requestLimit),offset:String(requestOffset)});if($('rqSearch').value.trim())p.set('q',$('rqSearch').value.trim());if($('rqStatus').value)p.set('status',$('rqStatus').value);if($('rqModel').value.trim())p.set('model',$('rqModel').value.trim());if($('rqKey').value)p.set('key_id',$('rqKey').value);return p}
async function loadRequests(){if(!adminKey())return setStatus('请先连接管理员主密钥','bad');try{if(!overview)overview=await api('/api/admin/overview');fillKeyFilter(overview.api_keys||[]);const data=await api('/api/admin/requests?'+requestQuery());$('requestsBody').innerHTML=(data.data||[]).map(r=>`<tr class="clickable" onclick="showRequest('${esc(r.request_id)}')"><td>${fmtTime(r.recorded_at)}</td><td>${pill(r.status||'-',r.status==='completed'?'ok':'bad')}</td><td>${esc(r.api_key_name||r.api_key_id||'-')}</td><td><code>${esc(r.requested_model||'-')}</code></td><td><code>${esc(actualModel(r))}</code></td><td>${fmtMs(r.timings?.first_token_ms)}</td><td>${fmtMs(r.timings?.total_ms)}</td><td>${esc(r.usage?.total_tokens??0)}</td></tr>`).join('')||'<tr><td colspan="8" class="muted">没有匹配记录</td></tr>';const from=data.total?requestOffset+1:0,to=Math.min(requestOffset+requestLimit,data.total);$('pageInfo').textContent=`${from}-${to} / ${data.total}`;$('prevPage').disabled=requestOffset===0;$('nextPage').disabled=requestOffset+requestLimit>=data.total;setStatus('请求记录已加载','ok')}catch(e){setStatus('加载请求记录失败：'+e.message,'bad')}}
$('rqFilter').onclick=()=>{requestOffset=0;loadRequests()};$('prevPage').onclick=()=>{requestOffset=Math.max(0,requestOffset-requestLimit);loadRequests()};$('nextPage').onclick=()=>{requestOffset+=requestLimit;loadRequests()};async function showRequest(id){try{const r=await api('/api/admin/requests/'+encodeURIComponent(id));const safe={...r};$('requestDetail').innerHTML=`<div><b>${esc(r.request_id)}</b> ${pill(r.status,r.status==='completed'?'ok':'bad')}</div><p class="muted">Key: ${esc(r.api_key_name||r.api_key_id||'-')} · Client: ${esc(r.client_id||'-')} · ${fmtTime(r.recorded_at)}</p><p>请求模型 <code>${esc(r.requested_model||'-')}</code> → 实际 <code>${esc(actualModel(r))}</code></p><p>Prompt 字符 ${esc(r.prompt_chars??'-')} · Completion 字符 ${esc(r.completion_chars??'-')} · stream=${esc(r.stream??'-')} · mode=${esc(r.prompt_mode??'-')}</p>${r.error?`<p class="bad">${esc(r.error)}</p>`:''}<h3>Usage</h3><pre>${esc(JSON.stringify(r.usage||{},null,2))}</pre><h3>Timings</h3><pre>${esc(JSON.stringify(r.timings||{},null,2))}</pre><h3>Diagnostics</h3><pre>${esc(JSON.stringify(r.diagnostics||{},null,2))}</pre>`}catch(e){setStatus('加载详情失败：'+e.message,'bad')}}window.showRequest=showRequest;
function renderDocs(){const base=location.origin;$('docBase').textContent=base+'/v1';$('curlCode').textContent=`curl -N ${base}/v1/chat/completions \\\n  -H "Authorization: Bearer YOUR_API_KEY" \\\n  -H "Content-Type: application/json" \\\n  -d '{\n    "model":"default",\n    "messages":[{"role":"user","content":"你好"}],\n    "stream":true\n  }'`;$('pythonCode').textContent=`from openai import OpenAI\n\nclient = OpenAI(\n    api_key="YOUR_API_KEY",\n    base_url="${base}/v1",\n)\n\nstream = client.chat.completions.create(\n    model="default",\n    messages=[{"role":"user","content":"你好"}],\n    stream=True,\n)\nfor chunk in stream:\n    print(chunk.choices[0].delta.content or "", end="", flush=True)`}document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>navigator.clipboard.writeText($(b.dataset.copy).textContent||''));
async function loadPlaygroundModels(){try{if(!overview&&adminKey())overview=await api('/api/admin/overview');if(overview)fillModelOptions()}catch(_){} }
function pgAuthKey(){return $('pgKey').value.trim()||adminKey()} function appendOutput(text){$('pgOutput').textContent+=text;$('pgOutput').scrollTop=$('pgOutput').scrollHeight}
$('pgRun').onclick=async()=>{const key=pgAuthKey(),prompt=$('pgPrompt').value.trim(),model=$('pgModel').value||'default',stream=$('pgStream').checked;if(!key)return setStatus('测试场需要 API Key','bad');if(!prompt)return setStatus('请输入 Prompt','bad');$('pgOutput').textContent='';$('pgRaw').textContent='';$('pgMeta').innerHTML='<pre>-</pre>';$('pgState').textContent='请求中…';const started=performance.now();try{const r=await fetch('/v1/chat/completions',{method:'POST',headers:{Authorization:'Bearer '+key,'Content-Type':'application/json'},body:JSON.stringify({model,messages:[{role:'user',content:prompt}],stream,prompt_mode:$('pgMode').value})});if(!r.ok){throw new Error(r.status+' '+await r.text())}if(!stream){const data=await r.json();appendOutput(data.choices?.[0]?.message?.content||'');$('pgRaw').textContent=JSON.stringify(data,null,2);$('pgMeta').innerHTML='<pre>'+esc(JSON.stringify({usage:data.usage,chat2api:data.chat2api},null,2))+'</pre>';$('pgState').textContent='完成 · '+fmtMs(performance.now()-started);return}const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='',finalMeta=null;while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let idx;while((idx=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,idx);buffer=buffer.slice(idx+2);for(const line of block.split('\n')){if(!line.startsWith('data: '))continue;const payload=line.slice(6);$('pgRaw').textContent+='data: '+payload+'\n\n';if(payload==='[DONE]')continue;let data;try{data=JSON.parse(payload)}catch(_){continue}if(data.error)throw new Error(data.error.message||JSON.stringify(data.error));const delta=data.choices?.[0]?.delta?.content;if(delta)appendOutput(delta);if(data.usage||data.chat2api)finalMeta={usage:data.usage,chat2api:data.chat2api}}}}if(finalMeta)$('pgMeta').innerHTML='<pre>'+esc(JSON.stringify(finalMeta,null,2))+'</pre>';$('pgState').textContent='完成 · '+fmtMs(performance.now()-started)}catch(e){$('pgState').innerHTML='<span class="bad">失败：'+esc(e.message)+'</span>'}};
const initial=(location.hash||'#'+INITIAL_VIEW).slice(1);showView(titles[initial]?initial:INITIAL_VIEW);if(adminKey()&&INITIAL_VIEW!=='docs')loadOverview();setInterval(()=>{const view=(location.hash||'#overview').slice(1);if(adminKey()&&!document.hidden&&view==='overview')loadOverview()},7000);
</script></body></html>'''


def admin_response(initial_view: str = "overview") -> HTMLResponse:
    safe_view = initial_view if initial_view in {"overview", "keys", "requests", "docs", "playground"} else "overview"
    return HTMLResponse(
        ADMIN_HTML.replace("__INITIAL_VIEW__", safe_view),
        headers={"Cache-Control": "no-store"},
    )
